actionCellButton.customFunction:
const req = {"method": "setLight", "params": true, "timeout": 60000};
widgetContext.showSuccessToast('Đang gửi Bật đèn tới ' + entityName + ' (SF12, có thể mất vài giây)...', 3000);
widgetContext.deviceService.sendTwoWayRpcCommand(entityId.id, req).subscribe(
  (resp) => {
    if (resp && resp.success === false) {
      widgetContext.showErrorToast(entityName + ': lỗi ' + (resp.error || 'không rõ'), 'top', 'center', null, true);
    } else {
      widgetContext.showSuccessToast(entityName + ': đã bật đèn', 3000);
    }
  },
  (err) => widgetContext.showErrorToast(entityName + ': không phản hồi (timeout hoặc gateway offline)', 'top', 'center', null, true)
);

